css:
:root{
  --blue:#0088C0;
  --teal:#00A890;
  --grey:#888888;
  --deep:#0A3A52;
  --tint:#eef6fb;
  --tint2:#e8f7f2;
  --ink:#1b2733;
  --line:#e2e8ee;
  --grad:linear-gradient(135deg,var(--blue),var(--teal));
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  color:var(--ink);
  background:#ffffff;
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
  display:flex;
  flex-direction:column;
  min-height:100vh;
}
a{color:var(--blue);text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;display:block}
:focus-visible{outline:3px solid var(--blue);outline-offset:2px}

/* Skip link */
.skip{position:absolute;left:-999px;top:auto;background:var(--deep);color:#fff;padding:10px 16px;border-radius:6px;z-index:200}
.skip:focus{left:16px;top:12px}

/* Utility bar */
.util{background:var(--deep);color:#dbe7ef;font-size:.85rem}
.util .wrap{display:flex;flex-wrap:wrap;gap:8px 22px;align-items:center;justify-content:center;padding:8px 20px}
.util a{color:#dbe7ef}
.util i{color:var(--teal);margin-right:6px}

/* Header */
.wrap{max-width:1160px;margin:0 auto}
header.site{border-bottom:1px solid var(--line);position:sticky;top:0;background:rgba(255,255,255,.96);backdrop-filter:blur(6px);z-index:100}
.bar{display:flex;align-items:center;justify-content:space-between;padding:14px 20px}
.brand{display:flex;align-items:center;gap:12px}
.brand img{height:46px;width:auto}
.brand .fallback{font-weight:800;font-size:1.25rem;color:var(--deep);letter-spacing:.2px}
nav.main ul{list-style:none;display:flex;align-items:center;gap:4px}
nav.main a.link{display:block;padding:10px 14px;color:var(--ink);font-weight:600;font-size:.95rem;border-radius:8px}
nav.main a.link:hover{background:var(--tint);text-decoration:none;color:var(--deep)}
.has-sub{position:relative}
.has-sub>button{
  font:inherit;font-weight:600;font-size:.95rem;color:var(--ink);
  background:none;border:0;cursor:pointer;padding:10px 14px;border-radius:8px;display:flex;align-items:center;gap:6px
}
.has-sub>button:hover{background:var(--tint);color:var(--deep)}
.has-sub>button i{font-size:.75rem;transition:transform .2s}
.submenu{
  position:absolute;top:100%;left:0;min-width:250px;background:#fff;border:1px solid var(--line);
  border-radius:10px;box-shadow:0 14px 34px rgba(10,58,82,.14);padding:8px;display:none;z-index:120
}
.submenu a{display:block;padding:9px 12px;border-radius:7px;color:var(--ink);font-size:.92rem;font-weight:500}
.submenu a:hover{background:var(--tint);text-decoration:none;color:var(--deep)}
.has-sub:hover .submenu,.has-sub.open .submenu{display:block}
.has-sub.open>button i{transform:rotate(180deg)}
.cta-head{background:var(--deep);color:#fff !important;padding:11px 18px !important;border-radius:8px !important}
.cta-head:hover{background:#0d4b6b;text-decoration:none}
.burger{display:none;background:none;border:0;font-size:1.5rem;color:var(--deep);cursor:pointer;padding:6px 10px}

/* Main confirmation */
main{flex:1;display:flex;align-items:center;justify-content:center;background:
  radial-gradient(circle at 15% 15%,var(--tint2),transparent 45%),
  radial-gradient(circle at 85% 20%,var(--tint),transparent 42%),
  var(--tint);
  padding:64px 20px}
.card{
  background:#fff;max-width:640px;width:100%;border-radius:20px;
  box-shadow:0 24px 60px rgba(10,58,82,.12);
  border:1px solid var(--line);
  overflow:hidden;text-align:center
}
.card .accent{height:6px;background:var(--grad)}
.card .body{padding:52px 44px 48px}
.mark{
  width:96px;height:96px;border-radius:50%;margin:0 auto 26px;
  background:var(--grad);display:flex;align-items:center;justify-content:center;
  box-shadow:0 12px 26px rgba(0,136,192,.32)
}
.mark i{color:#fff;font-size:2.6rem;line-height:1}
h1{font-size:2rem;line-height:1.2;color:var(--deep);font-weight:800;letter-spacing:-.3px;margin-bottom:16px}
.lead{font-size:1.08rem;color:#3c4a57;margin:0 auto 12px;max-width:500px}
.hours{font-size:1rem;color:var(--grey);margin:0 auto 32px;max-width:500px}
.hours strong{color:var(--deep)}
.btn{
  display:inline-flex;align-items:center;gap:10px;background:var(--deep);color:#fff;
  font-weight:700;font-size:1.02rem;padding:15px 30px;border-radius:10px;
  box-shadow:0 8px 20px rgba(10,58,82,.22);transition:transform .15s,background .2s
}
.btn:hover{background:#0d4b6b;text-decoration:none;transform:translateY(-2px)}
.btn i{font-size:.95rem}
.callrow{margin-top:26px;padding-top:24px;border-top:1px solid var(--line);font-size:.97rem;color:#3c4a57}
.callrow .label{display:block;color:var(--grey);font-size:.85rem;text-transform:uppercase;letter-spacing:.6px;margin-bottom:8px}
.callrow a{font-weight:700;color:var(--blue);white-space:nowrap}
.callrow .sep{color:var(--line);margin:0 12px}

/* Footer */
footer.site{background:#fff;border-top:1px solid var(--line);color:#3c4a57}
.foot{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:36px;padding:52px 20px 30px}
.foot h4{color:var(--deep);font-size:.95rem;text-transform:uppercase;letter-spacing:.6px;margin-bottom:16px}
.foot img.flogo{height:44px;margin-bottom:14px}
.foot p{font-size:.93rem;margin-bottom:10px;max-width:320px}
.foot ul{list-style:none}
.foot li{margin-bottom:9px;font-size:.93rem}
.foot a{color:#3c4a57}
.foot a:hover{color:var(--blue)}
.foot .contact li{display:flex;gap:10px;align-items:flex-start}
.foot .contact i{color:var(--teal);margin-top:4px;width:16px;text-align:center}
.socials{display:flex;gap:10px;margin-top:16px;flex-wrap:wrap}
.socials a{
  width:38px;height:38px;border-radius:9px;background:var(--tint);color:var(--deep);
  display:flex;align-items:center;justify-content:center;font-size:1rem
}
.socials a:hover{background:var(--grad);color:#fff;text-decoration:none}
.legal{border-top:1px solid var(--line);padding:18px 20px;text-align:center;font-size:.85rem;color:var(--grey)}
.legal a{color:var(--grey)}

@media(max-width:860px){
  .burger{display:block}
  nav.main{position:absolute;top:100%;left:0;right:0;background:#fff;border-bottom:1px solid var(--line);
    box-shadow:0 18px 30px rgba(10,58,82,.10);display:none;padding:10px}
  header.site.nav-open nav.main{display:block}
  nav.main ul{flex-direction:column;align-items:stretch;gap:2px}
  nav.main a.link,.has-sub>button{width:100%;font-size:1rem}
  .has-sub>button{justify-content:space-between}
  .submenu{position:static;box-shadow:none;border:0;padding:2px 0 6px 14px;min-width:0}
  .cta-head{text-align:center;justify-content:center;display:flex}
  .foot{grid-template-columns:1fr;gap:30px}
}
@media(max-width:520px){
  .card .body{padding:40px 24px 40px}
  h1{font-size:1.6rem}
  .callrow .sep{display:block;height:6px;margin:0}
}
@media(prefers-reduced-motion:reduce){*{transition:none !important;scroll-behavior:auto !important}}
